import '../../features/intelligence/domain/intelligence_library.dart';

/// Spanish wording for ORVIKA's curated offline intelligence reference.
class SpanishIntelligenceContent {
  SpanishIntelligenceContent._();

  static const Map<String, Map<String, String>> _entries = {
    'url-http': {'title':'HTTP sin cifrar','signal':'Una dirección web comienza por http:// en lugar de https://.','meaning':'La conexión no utiliza TLS para proteger los datos durante la transmisión. La información intercambiada puede quedar expuesta o ser modificada en la red.','action':'Evita introducir contraseñas o datos de pago. Accede a la organización mediante un marcador fiable o una dirección verificada de forma independiente.','limit':'HTTPS protege la conexión; no demuestra que el sitio web sea legítimo.'},
    'url-userinfo': {'title':'Información de usuario engañosa en una URL','signal':'Una URL contiene texto antes del símbolo @, por ejemplo https://trusted.example@unknown.example/.','meaning':'Los navegadores interpretan como nombre de host el texto que aparece después de @. El texto aparentemente fiable anterior puede estar diseñado para distraer.','action':'Lee el nombre de host real justo después de @ y verifica el dominio registrable antes de visitar el sitio.','limit':'La información de usuario en una URL es inusual, pero por sí sola no demuestra una intención maliciosa.'},
    'url-punycode': {'title':'Dominio internacionalizado / Punycode','signal':'Un nombre de host contiene una etiqueta xn-- o caracteres visualmente similares.','meaning':'Los nombres de dominio internacionalizados pueden utilizar caracteres de distintos sistemas de escritura que se parecen a letras latinas.','action':'Comprueba la ortografía exacta y el titular del dominio mediante una fuente fiable. No te fíes únicamente de un logotipo o nombre conocido.','limit':'Muchos sitios legítimos utilizan nombres de dominio internacionalizados.'},
    'url-subdomains': {'title':'Cadena profunda de subdominios','signal':'Un nombre de host contiene varias etiquetas, como login.account.example.invalid.','meaning':'El dominio registrado no tiene por qué ser la primera palabra conocida de la dirección. Los atacantes pueden colocar nombres de marcas en subdominios que controlan.','action':'Lee el nombre de host de derecha a izquierda e identifica el dominio registrable. Verifícalo de forma independiente.','limit':'Las cadenas largas de subdominios también tienen usos legítimos.'},
    'message-urgency': {'title':'Urgencia y presión','signal':'Un mensaje exige actuar de inmediato, amenaza con cerrar una cuenta o impone un plazo artificial.','meaning':'La presión puede desalentar la verificación independiente y empujar al destinatario a actuar sin pensar.','action':'Haz una pausa. Contacta con la organización mediante una aplicación, sitio web o número oficial que ya conozcas, no mediante los datos del mensaje.','limit':'El lenguaje urgente también puede aparecer en comunicaciones legítimas; el contexto importa.'},
    'message-credentials': {'title':'Solicitud de credenciales u OTP','signal':'Un remitente solicita una contraseña, OTP, código de recuperación o aprobación de una solicitud de inicio de sesión inesperada.','meaning':'Estos secretos o aprobaciones pueden dar acceso a una cuenta o autorizar una transacción.','action':'Nunca reveles contraseñas ni OTP. Rechaza las solicitudes de aprobación inesperadas y contacta con el servicio por su canal oficial.','limit':'Una coincidencia de palabras clave solo identifica un tema; no determina quién envió el mensaje ni su intención.'},
    'message-payment': {'title':'Pago o reembolso inesperado','signal':'Un mensaje solicita una transferencia, una tasa de gestión, una acción de reembolso o un pago para desbloquear un beneficio.','meaning':'Las instrucciones financieras inesperadas pueden utilizarse para desviar fondos o recopilar datos de pago.','action':'Verifica el beneficiario, el importe y el motivo mediante un canal fiable distinto antes de actuar.','limit':'El lenguaje relacionado con pagos también es habitual en facturas y avisos de servicio legítimos.'},
    'qr-payment': {'title':'Solicitud de pago mediante QR','signal':'Un contenido QR utiliza un esquema de pago como upi://pay.','meaning':'El escaneo puede preparar un pago a un destinatario. Un código QR no autentica al beneficiario ni garantiza que el importe sea correcto.','action':'Comprueba el nombre del beneficiario, el identificador UPI y el importe en la aplicación de pago antes de autorizar. Cancela si algo no coincide.','limit':'Un contenido de pago no es fraudulento por naturaleza; verifica los datos de la transacción.'},
    'qr-action': {'title':'Código QR con un enlace de acción','signal':'Un contenido QR incluye una acción web, telefónica, de correo electrónico, SMS o específica de una aplicación.','meaning':'El contenido puede abrir un destino o rellenar una acción cuando otra aplicación lo procesa.','action':'Examina primero el contenido decodificado. No abras enlaces desconocidos ni apruebes acciones rellenadas previamente sin verificarlas.','limit':'El tipo de contenido por sí solo no permite determinar si su origen es fiable.'},
    'account-mfa': {'title':'Aprobación MFA inesperada','signal':'Recibes una solicitud de aprobación de inicio de sesión o un código de un solo uso que no has solicitado.','meaning':'Alguien puede estar intentando iniciar sesión con el identificador y la contraseña de tu cuenta, o el código puede haberse generado por error.','action':'Rechaza la solicitud, no compartas el código, cambia la contraseña mediante el servicio oficial si procede y revisa las sesiones activas.','limit':'Una solicitud inesperada es una señal de alerta, no la confirmación de que una cuenta esté comprometida.'},
    'url-shortener': {'title': 'Destino acortado u oculto', 'signal': 'Un enlace utiliza un acortador de URL u oculta el destino final tras una redirección.', 'meaning': 'La dirección visible no muestra el sitio al que llegarás finalmente. Las cadenas de redirecciones pueden ocultar un destino inesperado.', 'action': 'No confíes en el texto acortado. Usa una vista previa fiable o accede a la organización por tu cuenta; evita abrir enlaces acortados no solicitados.', 'limit': 'Los acortadores de URL se utilizan ampliamente en campañas y servicios legítimos.'},
    'url-lookalike': {'title': 'Dominio con escritura parecida', 'signal': 'Un dominio sustituye, añade o elimina caracteres para parecerse a una organización conocida.', 'meaning': 'Pequeñas diferencias ortográficas, palabras adicionales o caracteres intercambiados pueden hacer que un dominio controlado por un atacante parezca familiar.', 'action': 'Compara carácter por carácter el dominio registrable completo con una dirección obtenida de forma independiente.', 'limit': 'Un nombre parecido es motivo para verificar, no una prueba de titularidad maliciosa.'},
    'url-download': {'title': 'Descarga de archivo inesperada', 'signal': 'Un sitio web o mensaje solicita inesperadamente descargar un ejecutable, script, archivo comprimido o paquete de aplicación móvil.', 'meaning': 'Un archivo descargado puede instalar software, solicitar permisos excesivos o aprovechar una aplicación vulnerable.', 'action': 'No ejecutes archivos inesperados. Obtén el software desde la tienda de confianza de la plataforma o desde el sitio del editor verificado de forma independiente.', 'limit': 'El software legítimo también se distribuye como archivo descargable; verifica editor, origen e integridad.'},
    'url-certificate': {'title': 'Aviso del certificado HTTPS', 'signal': 'El navegador informa de un certificado del sitio no válido, caducado, no coincidente o no confiable.', 'meaning': 'El navegador no puede establecer la conexión cifrada autenticada esperada con ese nombre de host.', 'action': 'Detente y no omitas el aviso para introducir credenciales o datos de pago. Comprueba la dirección e inténtalo más tarde.', 'limit': 'Los errores de certificado pueden deberse a una configuración incorrecta o al reloj del dispositivo; no identifican la causa.'},
    'url-permission': {'title': 'Solicitud inesperada de permisos del navegador', 'signal': 'Un sitio solicita inesperadamente acceso a notificaciones, cámara, micrófono, ubicación o archivos.', 'meaning': 'Un permiso puede exponer funciones sensibles del dispositivo o activar notificaciones persistentes no deseadas.', 'action': 'Deniega los permisos que no sean necesarios para la tarea. Revisa y revoca los permisos del sitio en la configuración del navegador.', 'limit': 'Algunos servicios legítimos necesitan permisos para funciones concretas; evalúa el propósito y el origen.'},
    'message-secrecy': {'title': 'Solicitud de secreto o aislamiento', 'signal': 'Un remitente te pide que no hables de una solicitud con familiares, compañeros, tu banco o la organización implicada.', 'meaning': 'El aislamiento puede impedir una segunda opinión y hacer más eficaz la suplantación o la presión para pagar.', 'action': 'Haz una pausa y verifica la solicitud por otra vía. Un proceso legítimo debería admitir una comprobación razonable.', 'limit': 'Las peticiones de confidencialidad pueden ser legítimas en algunos contextos; importan la urgencia y la acción solicitada.'},
    'message-remote-access': {'title': 'Engaño para obtener acceso remoto o compartir pantalla', 'signal': 'Un remitente pide instalar software de soporte remoto, compartir la pantalla o permitir el control del dispositivo.', 'meaning': 'El acceso remoto puede exponer mensajes, sesiones bancarias, códigos de autenticación y archivos, o permitir acciones en tu nombre.', 'action': 'No instales nada ni concedas acceso ante una solicitud no solicitada. Contacta con la organización por un canal verificado por separado.', 'limit': 'Las herramientas de soporte remoto tienen usos legítimos cuando tú inicias el soporte con un proveedor de confianza.'},
    'message-gift-card': {'title': 'Pago con tarjetas regalo o criptomonedas', 'signal': 'Un mensaje solicita códigos de tarjetas regalo, criptomonedas, vales u otro pago difícil de revertir.', 'meaning': 'Estos métodos de pago pueden ser difíciles o imposibles de recuperar una vez transferidos.', 'action': 'No compres ni transfieras códigos o criptomonedas bajo presión. Verifica la solicitud con el supuesto remitente mediante un canal conocido.', 'limit': 'Estos métodos tienen usos legítimos; la preocupación es la petición no solicitada y su contexto.'},
    'message-secrets': {'title': 'Solicitud de datos bancarios o de identidad sensibles', 'signal': 'Un mensaje pide el código de seguridad de la tarjeta, un número de identidad completo, credenciales de cuenta o copias de documentos de identidad.', 'meaning': 'Estos datos pueden facilitar la toma de control de cuentas, el uso indebido de identidad o transacciones no autorizadas.', 'action': 'No envíes datos sensibles por respuesta o chat. Utiliza solo un proceso oficial verificado que hayas iniciado tú.', 'limit': 'Algunos procesos regulados requieren verificar la identidad; comprueba el canal y la necesidad antes de compartir.'},
    'qr-wifi': {'title': 'Código QR con credenciales Wi-Fi', 'signal': 'El contenido descodificado de un QR incluye el nombre de una red Wi-Fi y su contraseña.', 'meaning': 'Al conectarte, tu dispositivo puede unirse a una red controlada por otra persona; los riesgos dependen de su configuración.', 'action': 'Conéctate solo a redes de confianza. Evita actividades sensibles en redes desconocidas y utiliza las protecciones del dispositivo.', 'limit': 'Los códigos QR de Wi-Fi son una función práctica habitual y no son maliciosos por sí mismos.'},
    'qr-contact': {'title': 'Código QR con acción de contacto o mensaje', 'signal': 'Un contenido QR incluye una vCard, un número de teléfono, una dirección de correo o un SMS precompletado.', 'meaning': 'Al importar o activar el contenido se puede añadir un contacto o preparar una comunicación con un destino no verificado.', 'action': 'Revisa el nombre, número, dirección y mensaje mostrados antes de guardar o enviar nada.', 'limit': 'Los QR de contacto se usan habitualmente para compartir datos legítimos; verifica los detalles antes de actuar.'},
    'account-recovery': {'title': 'Actividad inesperada de recuperación de cuenta', 'signal': 'Recibes sin solicitarlo un aviso de restablecimiento de contraseña, una petición de código de recuperación o una alerta de cambio de datos de recuperación.', 'meaning': 'Alguien puede estar intentando acceder a una cuenta o tomar su control; la notificación también podría ser spam.', 'action': 'No compartas códigos de recuperación. Abre el servicio con su aplicación oficial o un marcador fiable, revisa la actividad y protege los métodos de recuperación.', 'limit': 'Una notificación por sí sola no confirma que la cuenta haya sido tomada.'},
  };

  static IntelligenceEntry localize(IntelligenceEntry entry, String languageCode) {
    if (languageCode != 'es') return entry;
    final values = _entries[entry.id];
    if (values == null) return entry;
    return IntelligenceEntry(id: entry.id, title: values['title']!, category: entry.category,
      signal: values['signal']!, meaning: values['meaning']!, action: values['action']!, limit: values['limit']!);
  }
}
